script:
// Badge (ds-metrics §6): capsule; size sm / md / lg = 20 / 24 / 28 high, padding h 6 / 8 / 10, captionMedium /
// captionStrong / bodySmallStrong. neutral = el3 + el16; tinted styles = the tone color on a 14% fill of itself.
param title: string
param style: "neutral" | "accent" | "success" | "warning" | "error" = "neutral"
param size: "sm" | "md" | "lg" = "md"
let tone = style == "accent" ? @color.accentPrimary : style == "success" ? @color.success : style == "warning" ? @color.warning : @color.error
